package com.witchersbestiary.client.merchant;
import com.witchersbestiary.merchant.*;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.ingame.HandledScreen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.entity.player.PlayerInventory;import net.minecraft.item.*;import net.minecraft.text.Text;import net.minecraft.util.Identifier;
public final class MerchantScreen extends HandledScreen<MerchantHandler> {
 private int page;public MerchantScreen(MerchantHandler h,PlayerInventory inventory,Text title){super(h,inventory,title);backgroundWidth=300;backgroundHeight=220;}
 private Text text(String key){return Text.translatable("merchant.witchersbestiary."+key);}
 public void update(){clearAndInit();}
 @Override protected void init(){super.init();var rows=handler.snapshot.getAsJsonArray("offers");if(rows==null)return;page=Math.clamp(page,0,Math.max(0,(rows.size()-1)/5));for(int i=0;i<5&&page*5+i<rows.size();i++){var row=rows.get(page*5+i).getAsJsonObject();int yy=y+42+i*29;var b=addDrawableChild(ButtonWidget.builder(text("buy"),button->{if(handler.session!=null)net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new MerchantPackets.Buy(handler.syncId,handler.session,handler.nonce,row.get("id").getAsString()));}).dimensions(x+226,yy,66,20).build());String reason=row.get("stock").getAsInt()<=0?"stock":handler.snapshot.get("balance").getAsLong()<row.get("price").getAsLong()?"funds":"";b.active=reason.isEmpty();if(!reason.isEmpty())b.setTooltip(net.minecraft.client.gui.tooltip.Tooltip.of(text(reason)));}
 addDrawableChild(ButtonWidget.builder(Text.literal("<"),b->{page=Math.max(0,page-1);clearAndInit();}).dimensions(x+6,y+190,25,18).build());addDrawableChild(ButtonWidget.builder(Text.literal(">"),b->{page=Math.min((rows.size()-1)/5,page+1);clearAndInit();}).dimensions(x+269,y+190,25,18).build());}
 private ItemStack item(com.google.gson.JsonObject row){return new ItemStack(net.minecraft.registry.Registries.ITEM.get(Identifier.of(row.get("item").getAsString())),row.get("count").getAsInt());}
 @Override protected void drawBackground(DrawContext c,float delta,int mx,int my){c.fill(x,y,x+300,y+220,0xff2e251d);c.fill(x+2,y+2,x+298,y+218,0xff51412d);c.fill(x+4,y+36,x+296,y+187,0xff211e1a);var rows=handler.snapshot.getAsJsonArray("offers");if(rows==null)return;for(int i=0;i<5&&page*5+i<rows.size();i++){var row=rows.get(page*5+i).getAsJsonObject();int yy=y+42+i*29;var stack=item(row);c.drawItem(stack,x+9,yy);c.drawItemInSlot(textRenderer,stack,x+9,yy);c.drawText(textRenderer,textRenderer.trimToWidth(stack.getName().getString(),188),x+30,yy,0xffead6ad,false);c.drawText(textRenderer,Text.translatable("merchant.witchersbestiary.price",row.get("price").getAsLong(),row.get("stock").getAsInt()),x+30,yy+11,0xffc6b48f,false);}}
 @Override protected void drawForeground(DrawContext c,int mx,int my){c.drawText(textRenderer,title,8,7,0xffead6ad,false);if(handler.snapshot.has("balance")){var mode=text("mode."+handler.snapshot.get("mode").getAsString().toLowerCase(java.util.Locale.ROOT));c.drawText(textRenderer,mode,292-textRenderer.getWidth(mode),7,0xffc6b48f,false);c.drawText(textRenderer,Text.translatable("merchant.witchersbestiary.balance",handler.snapshot.get("balance").getAsLong()),8,22,0xffdfbd73,false);String status=handler.snapshot.get("message").getAsString();if(!status.isEmpty())c.drawText(textRenderer,textRenderer.trimToWidth(text(status).getString(),230),36,195,0xffead6ad,false);}}
 @Override public void render(DrawContext c,int mx,int my,float delta){super.render(c,mx,my,delta);drawMouseoverTooltip(c,mx,my);var rows=handler.snapshot.getAsJsonArray("offers");if(rows!=null)for(int i=0;i<5&&page*5+i<rows.size();i++){int yy=y+42+i*29;if(mx>=x+8&&mx<x+218&&my>=yy&&my<yy+24)c.drawItemTooltip(textRenderer,item(rows.get(page*5+i).getAsJsonObject()),mx,my);}}
}
